/**
 * Demo catalog — single source of truth for:
 *  - supabase/seed.sql (generated by `npm run seed:generate`)
 *  - demo mode (when Supabase environment variables are not configured)
 *
 * Every product here is flagged as `is_demo` and shows an "Exemplo" badge in
 * the store. Replace them with the real catalog through the admin panel.
 *
 * This file must stay dependency-free (no imports) so it can be executed by
 * Node directly (type stripping) from the seed generator script.
 */

export type DemoCategory = {
  slug: string;
  name: string;
  description: string;
  icon: string;
  parent?: string;
  sort: number;
};

export type DemoVariant = { name: string; price?: number; stock: number };

export type DemoProduct = {
  slug: string;
  name: string;
  category: string; // subcategory slug
  short: string;
  description: string;
  price: number;
  promo?: number;
  stock: number;
  material?: string;
  weight: number; // grams
  dims?: [number, number, number]; // width, height, length (cm)
  featured?: boolean;
  isNew?: boolean;
  sales?: number;
  variantLabel?: string;
  variants?: DemoVariant[];
};

export type DemoReview = { product: string; author: string; rating: number; title: string; comment: string };

export type DemoBanner = {
  title: string;
  subtitle: string;
  eyebrow: string;
  link: string;
  button: string;
  position: 'hero' | 'promo';
  theme: 'navy' | 'gold' | 'beige';
  sort: number;
};

export type DemoCoupon = {
  code: string;
  description: string;
  type: 'percent' | 'fixed' | 'free_shipping';
  value: number;
  min: number;
  perUser: number | null;
};

/** Deterministic UUID derived from a string (stable between seed and demo mode). */
export function stableUuid(input: string): string {
  const hash = (seed: number) => {
    let h = seed >>> 0;
    for (let i = 0; i < input.length; i++) {
      h ^= input.charCodeAt(i);
      h = Math.imul(h, 16777619) >>> 0;
    }
    return h.toString(16).padStart(8, '0');
  };
  const hex = hash(2166136261) + hash(374761393) + hash(668265263) + hash(3266489917);
  return [
    hex.slice(0, 8),
    hex.slice(8, 12),
    '4' + hex.slice(13, 16),
    '8' + hex.slice(17, 20),
    hex.slice(20, 32),
  ].join('-');
}

